float random2(vec2 par){
  vec2 pp = floor(par * 200.);
  return fract(sin(dot(pp.xy,vec2(12.9898,78.233))) * 43758.5453);
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
  vec2 uv = fragCoord/iResolution.xy;

  float angle = iTime * .1;

  vec2 UV = (uv - .5);
  mat2 rotateMatrix0 = mat2(cos(angle),-sin(angle),sin(angle),cos(angle));
  vec2 normalized0 =.5* normalize(UV * rotateMatrix0);
  mat2 rotateMatrix1 = mat2(cos(angle),sin(angle),-sin(angle),cos(angle));
  vec2 normalized1 =.5* normalize(UV * rotateMatrix1);

  float textmask = random2(normalized0) * random2(normalized1);
  float umask = pow(2.* length(UV),2.);

  float mask = umask  * textmask;
  float threshold = .82;
  mask = smoothstep(threshold - .1,threshold + .1,mask);

  fragColor =   vec4(mask,mask,mask,1. );

}
